 "content": "from collections import Counter


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # The 2 rail spans one complete axis. Mark the cell-line immediately
    # beyond the colored shape, on the side away from the rail.
    rail = None
    for c in range(w):
        if all(g[r][c] == 2 for r in range(h)):
            rail = ('v', c)
            break
    if rail is None:
        for r in range(h):
            if all(g[r][c] == 2 for c in range(w)):
                rail = ('h', r)
                break
    if rail is None:
        return g

    points = [(r, c) for r in range(h) for c in range(w)
              if g[r][c] not in (bg, 2)]
    if not points:
        return g

    axis, pos = rail
    if axis == 'v':
        min_c = min(c for _, c in points)
        max_c = max(c for _, c in points)
        mark = max_c + 1 if min_c > pos else min_c - 1
        if 0 <= mark < w:
            for r in range(h):
                g[r][mark] = 8
    else:
        min_r = min(r for r, _ in points)
        max_r = max(r for r, _ in points)
        mark = max_r + 1 if min_r > pos else min_r - 1
        if 0 <= mark < h:
            g[mark] = [8] * w
    return g


if __name__ == '__main__':
    demo = [[5] * 14 for _ in range(27)]
    for r in range(27):
        demo[r][5] = 2
    for r in range(10, 19):
        demo[r][4] = 1
    result = transform(demo)
    assert all(result[r][3] == 8 for r in range(27))
    assert all(result[r][4] == (1 if 10 <= r <= 18 else 5) for r in range(27))

    test = [[5, 2] + [5] * 17 for _ in range(10)]
    test[6][2:4] = [7, 7]
    test[7][3] = 7
    result = transform(test)
    assert all(result[r][4] == 8 for r in range(10))
    assert result[6][2:4] == [7, 7] and result[7][3] == 7
    print(result)
    print('DEMO_AND_TEST_CHECKS_OK')
